const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const caboFrio = ee.Geometry.Point([-42.02, -22.88]); // Approximate center of Cabo Frio
  const region = caboFrio.buffer(20000); // 20 km buffer around Cabo Frio to define the "sea zone"
  const startDate = '2023-09-01';
  const endDate = '2023-09-30';

  // 2. Data Acquisition & Check
  let sstCollection = ee.ImageCollection('MODIS/006/MODIS_SST')
    .filterDate(startDate, endDate)
    .filterBounds(region);

  const initialSize = await sstCollection.size().getInfo();
  if (initialSize === 0) {
    console.log("No MODIS_SST images found for September 2023 in the specified region.");
    console.log("C1");
    return;
  }
  console.log(`Initial images found: ${initialSize}`);

  // Function to mask clouds and invalid pixels and scale SST
  const maskAndScaleSST = function(image) {
    // Quality_level: 0 = good, 1 = good, 2 = questionable, 3 = bad
    // Use quality_level <= 1 for good quality data
    const qualityMask = image.select('quality_level').lte(1);

    // Apply scaling factor (MODIS_SST band 'sst' is in K * 100)
    // Convert to Celsius: (K / 100) - 273.15
    const sstCelsius = image.select('sst').multiply(0.01).subtract(273.15);

    // Mask out land areas and low quality pixels
    // Use `image.select('day_night_flag')` == 0 for day, 1 for night. Here we don't filter.
    return sstCelsius.updateMask(qualityMask).rename('sst_celsius');
  };

  const processedSST = sstCollection.map(maskAndScaleSST);

  // Take the monthly mean to represent the period
  const meanSST = processedSST.mean();

  // Check for valid pixels after processing
  const pixelCount = await meanSST.select('sst_celsius').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: region,
    scale: 1000, // MODIS SST resolution is 1km
    maxPixels: 1e9
  }).get('sst_celsius').getInfo();

  if (pixelCount === 0 || pixelCount === null) {
    console.log("No valid SST pixels remaining after cloud masking and processing.");
    console.log("C2");
    return;
  }
  console.log(`Valid pixels after processing: ${pixelCount}`);

  // 3. Calculation of Temperature Gradient
  // The 'sst_celsius' band resolution is 1 km.
  // The gradient magnitude will be in degrees Celsius per kilometer.
  const gradientMagnitude = meanSST.select('sst_celsius').gradient().unitScale(0,100).magnitude();
  // `unitScale` is for visualization, let's remove it and use the raw gradient for calculation.
  const rawGradient = meanSST.select('sst_celsius').gradient().magnitude();

  // Define the threshold for the gradient (5 degrees Celsius / km)
  const gradientThreshold = 5; // degrees Celsius per kilometer

  // Find pixels where the gradient magnitude is greater than the threshold
  const highGradientPixels = rawGradient.gt(gradientThreshold);

  // Reduce to find if any such pixels exist within the region
  const hasHighGradient = await highGradientPixels.reduceRegion({
    reducer: ee.Reducer.max(), // max() will return 1 if any pixel meets condition, 0 otherwise
    geometry: region,
    scale: 1000,
    maxPixels: 1e9
  }).get('magnitude').getInfo();

  // 4. Validation & Final Answer
  if (hasHighGradient === null) {
    console.log("Gradient calculation failed, returned null.");
    console.log("C3");
    return;
  }

  // The question asks for a gradient of *over* 5 degrees Celsius *over less than 10 kilometers*.
  // A gradient of G degrees/km means that over a distance of D km, the temperature change is G*D.
  // We want G * D > 5 and D < 10.
  // This phrasing is tricky. If the gradient magnitude is X degrees C per km, then over 1 km, the change is X.
  // If X > 5 degrees C/km, then over 1 km (which is < 10km), the change is > 5 degrees C.
  // So, checking if the gradient magnitude is > 5 degrees C per km is the direct interpretation.

  if (hasHighGradient === 1) {
    console.log("Stats: Max gradient > 5 degC/km found in September 2023 near Cabo Frio.");
    console.log("A"); // Yes
  } else {
    console.log("Stats: No gradient > 5 degC/km found in September 2023 near Cabo Frio.");
    console.log("B"); // No
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
